-- Generated by `shuru schema` from db/migrations/. Do not edit by hand.
-- A read-only overview of the whole database; the migrations are the source.

CREATE TABLE runs (
    id          INTEGER PRIMARY KEY,
    job         TEXT    NOT NULL,
    status      TEXT    NOT NULL CHECK (status IN ('running', 'ok', 'failed')),
    started_at  TEXT    NOT NULL,
    finished_at TEXT,
    duration_s  REAL,
    -- Short error summary for failed runs. Never holds scraped page content.
    error       TEXT,
    -- JSON object of counters and per-step timings (keys like "t_fetch_s").
    metrics     TEXT    NOT NULL DEFAULT '{}'
) STRICT;

CREATE INDEX runs_job_started ON runs (job, started_at);

CREATE TABLE health_samples (
    id               INTEGER PRIMARY KEY,
    run_id           INTEGER NOT NULL REFERENCES runs (id),
    taken_at         TEXT    NOT NULL,
    mem_total_mb     INTEGER,
    mem_available_mb INTEGER,
    swap_used_mb     INTEGER,
    load1            REAL,
    load5            REAL,
    load15           REAL,
    cpus             INTEGER NOT NULL,
    disk_total_mb    INTEGER NOT NULL,
    disk_free_mb     INTEGER NOT NULL,
    db_mb            REAL    NOT NULL,
    wal_mb           REAL    NOT NULL,
    cpu_temp_c       REAL,
    -- Raw bit flags from `vcgencmd get_throttled` (under-voltage, throttling).
    throttled        INTEGER,
    -- JSON object of failing checks, e.g. {"disk": "disk free 900 MB < 2000 MB"}.
    problems         TEXT    NOT NULL DEFAULT '{}'
) STRICT;

CREATE INDEX health_samples_taken ON health_samples (taken_at);

CREATE TABLE sources (
    id         INTEGER PRIMARY KEY,
    name       TEXT    NOT NULL UNIQUE,
    kind       TEXT    NOT NULL,
    -- Distant-supervision label: the language or variety this source is assumed
    -- to publish in. Every document from the source inherits it.
    label      TEXT    NOT NULL,
    licence    TEXT    NOT NULL DEFAULT '',
    -- 1 = never used for training; kept aside to test on an unseen source.
    holdout    INTEGER NOT NULL DEFAULT 0 CHECK (holdout IN (0, 1)),
    created_at TEXT    NOT NULL
) STRICT;

CREATE TABLE documents (
    id           INTEGER PRIMARY KEY,
    source_id    INTEGER NOT NULL REFERENCES sources (id),
    url          TEXT    NOT NULL UNIQUE,
    title        TEXT    NOT NULL DEFAULT '',
    -- Cleaned, lightly normalised text. Paragraphs are separated by newlines.
    text         TEXT    NOT NULL,
    -- SHA-256 of the folded text. UNIQUE makes exact-duplicate detection an index lookup.
    text_hash    TEXT    NOT NULL UNIQUE,
    -- Copied from the source at ingest time, so later config edits do not relabel history.
    label        TEXT    NOT NULL,
    published_at TEXT,
    fetched_at   TEXT    NOT NULL,
    -- Day used for date-based splits: published date if the page gave one, else fetch date.
    doc_date     TEXT    NOT NULL,
    n_chars      INTEGER NOT NULL,
    n_tokens     INTEGER NOT NULL,
    -- MinHash signature: num_perm unsigned 32-bit integers, little-endian.
    signature    BLOB    NOT NULL
) STRICT;

CREATE INDEX documents_source ON documents (source_id);

CREATE INDEX documents_date   ON documents (doc_date);

CREATE TABLE doc_bands (
    band   INTEGER NOT NULL,
    hash   INTEGER NOT NULL,
    doc_id INTEGER NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    PRIMARY KEY (band, hash, doc_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE urls (
    url           TEXT    PRIMARY KEY,
    source_id     INTEGER NOT NULL REFERENCES sources (id),
    status        TEXT    NOT NULL CHECK (status IN (
                      'stored',          -- became a document
                      'duplicate',       -- same text as an existing document
                      'near_duplicate',  -- almost the same text as an existing document
                      'rejected',        -- extracted but failed cleaning (too short, wrong script)
                      'blocked',         -- robots.txt or an off-site redirect
                      'error'            -- network or HTTP error
                  )),
    detail        TEXT    NOT NULL DEFAULT '',
    http_status   INTEGER,
    -- The document stored, or the existing document this URL duplicates.
    document_id   INTEGER REFERENCES documents (id) ON DELETE SET NULL,
    tries         INTEGER NOT NULL DEFAULT 1,
    first_seen_at TEXT    NOT NULL,
    last_tried_at TEXT    NOT NULL
) STRICT, WITHOUT ROWID;

CREATE INDEX urls_source_status ON urls (source_id, status);

CREATE TABLE http_cache (
    url           TEXT PRIMARY KEY,
    etag          TEXT,
    last_modified TEXT,
    checked_at    TEXT NOT NULL
) STRICT, WITHOUT ROWID;

CREATE VIRTUAL TABLE documents_fts USING fts5 (
    title,
    text,
    content = 'documents',
    content_rowid = 'id',
    tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TABLE models (
    id         INTEGER PRIMARY KEY,
    created_at TEXT    NOT NULL,
    -- File name inside the models folder.
    file_name  TEXT    NOT NULL,
    -- SHA-256 of the model file, checked every time the model is loaded.
    sha256     TEXT    NOT NULL UNIQUE,
    labels     TEXT    NOT NULL,  -- JSON array, in weight-row order
    params     TEXT    NOT NULL,  -- JSON object: hash_bits, n-gram range, epochs, ...
    metrics    TEXT    NOT NULL,  -- JSON object: per-split scores, baselines, cutoff
    is_active  INTEGER NOT NULL DEFAULT 0 CHECK (is_active IN (0, 1)),
    note       TEXT    NOT NULL DEFAULT ''
) STRICT;

CREATE UNIQUE INDEX models_one_active ON models (is_active) WHERE is_active = 1;

CREATE TABLE doc_scores (
    document_id INTEGER NOT NULL REFERENCES documents (id) ON DELETE CASCADE,
    model_id    INTEGER NOT NULL REFERENCES models (id) ON DELETE CASCADE,
    label       TEXT    NOT NULL,
    confidence  REAL    NOT NULL,  -- probability of the predicted label
    margin      REAL    NOT NULL,  -- gap to the runner-up; small = uncertain
    scored_at   TEXT    NOT NULL,
    PRIMARY KEY (document_id, model_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE news_feeds (
    id             INTEGER PRIMARY KEY,
    name           TEXT    NOT NULL UNIQUE,
    url            TEXT    NOT NULL,
    -- What the feed's outlet is assumed to publish, if known. '' = unknown.
    expected_label TEXT    NOT NULL DEFAULT '',
    created_at     TEXT    NOT NULL
) STRICT;

CREATE TABLE news_items (
    id           INTEGER PRIMARY KEY,
    feed_id      INTEGER NOT NULL REFERENCES news_feeds (id),
    -- The feed's guid for the entry, or its link.
    guid         TEXT    NOT NULL,
    url          TEXT    NOT NULL DEFAULT '',
    title        TEXT    NOT NULL,
    published_at TEXT,
    fetched_at   TEXT    NOT NULL,
    UNIQUE (feed_id, guid)
) STRICT;

CREATE INDEX news_items_fetched ON news_items (fetched_at);

CREATE TABLE news_scores (
    item_id    INTEGER NOT NULL REFERENCES news_items (id) ON DELETE CASCADE,
    model_id   INTEGER NOT NULL REFERENCES models (id) ON DELETE CASCADE,
    label      TEXT    NOT NULL,
    confidence REAL    NOT NULL,
    margin     REAL    NOT NULL,
    scored_at  TEXT    NOT NULL,
    PRIMARY KEY (item_id, model_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX news_scores_margin ON news_scores (model_id, margin);

CREATE TABLE drift_daily (
    day          TEXT    NOT NULL,
    feed_id      INTEGER NOT NULL REFERENCES news_feeds (id),
    model_id     INTEGER NOT NULL REFERENCES models (id) ON DELETE CASCADE,
    n            INTEGER NOT NULL,
    conf_sum     REAL    NOT NULL,
    conf_hist    TEXT    NOT NULL,  -- JSON array: counts of confidence in 10 equal bins
    label_counts TEXT    NOT NULL,  -- JSON object: predicted label -> count
    -- How often the prediction matched the feed's expected label (0 if none is set).
    n_expected   INTEGER NOT NULL DEFAULT 0,
    n_agree      INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (day, feed_id, model_id)
) STRICT, WITHOUT ROWID;

CREATE TABLE label_queue (
    item_id   INTEGER PRIMARY KEY REFERENCES news_items (id) ON DELETE CASCADE,
    model_id  INTEGER NOT NULL REFERENCES models (id) ON DELETE CASCADE,
    margin    REAL    NOT NULL,
    queued_at TEXT    NOT NULL,
    status    TEXT    NOT NULL DEFAULT 'pending'
                  CHECK (status IN ('pending', 'labelled', 'skipped'))
) STRICT;

CREATE INDEX label_queue_status ON label_queue (status, margin);

CREATE TABLE human_labels (
    item_id     INTEGER PRIMARY KEY REFERENCES news_items (id) ON DELETE CASCADE,
    label       TEXT    NOT NULL,
    annotator   TEXT    NOT NULL DEFAULT '',
    note        TEXT    NOT NULL DEFAULT '',
    labelled_at TEXT    NOT NULL
) STRICT;
